import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, Camara, Textura, Profundidad, Brillo, Paso, seguir, enCamino, Recorrido, tono, Chip, Contador, Ondas, golpe, h, clamp, interpolate, Easing} from './kit';

export const SUBS = {arriba: 230, acento: '#E7FF00'};

// ---- tiempos atados a la voz ----
const CIEN1 = en('cien'), PERS1 = en('personas'), GEO = en('geografía');
const DICIEMBRE = en('Diciembre'), D2004 = en('2004'), TAIL = en('Tailandia'), MAI1 = en('Mai'), NOTO = en('notó'), RARO = en('raro');
const MAR = en('mar'), RETIRABA = en('retiraba'), RAPIDO = en('rápido'), BURB = en('burbujas'), HIERVE = en('hierve');
const DOS = en('Dos'), SEMANAS = en('semanas'), PROF1 = en('profesor'), VIDEO = en('video'), TSU1 = en('tsunami');
const TILLY2 = en('Tilly', 2), RECON = en('reconoció'), SENAL = en('señales'), MAMA = en('mamá'), TSU2 = en('tsunami', 2);
const CREY = en('creyeron'), INSIST = en('insistió'), ASUST = en('asustada'), PAPA = en('papá'), AVISO = en('avisó'), HOTEL = en('hotel');
const EMPEZ = en('empezaron'), SACAR = en('sacar'), GENTE = en('gente'), PLAYA2 = en('playa', 2);
const MINUTOS = en('Minutos'), OLA = en('ola'), LLEGO = en('llegó'), ESE = en('Ese'), GOLP = en('golpeó'), COSTAS = en('costas'), OCEANO = en('océano');
const PERO = en('Pero'), MAI2 = en('Mai', 2), ISLA = en('isla'), NADIE = en('nadie');
const UNAS = en('Unas'), CIEN2 = en('cien', 2), VIVAS = en('vivas'), NINA2 = en('niña', 2), ATENC = en('atención'), CLASE3 = en('clase', 3);
const DALE = en('Dale'), ENVIA = en('envíaselo'), PROF2 = en('profesor', 2), USAR = en('usar');

const LIMA = '#E7FF00';
const clamp01 = (v: number) => Math.max(0, Math.min(1, v));

const Mundo: React.FC<{children: React.ReactNode; w?: number}> = ({children, w = 3600}) => <svg width={w} height={1920} viewBox={`-600 0 ${w} 1920`} style={{position: 'absolute', left: -600, top: 0, overflow: 'visible'}}>{children}</svg>;

type Parada = {t: number; x: number; y: number; zoom: number};
const Lugar: React.FC<{tipo: 'piel' | 'celulas' | 'fibra' | 'papel'; base: string; linea: string; luz: string; semilla: number; bx: number; by: number; bc: string; paradas: Parada[]; w?: number; hud?: React.ReactNode; children: React.ReactNode}> = ({tipo, base, linea, luz, semilla, bx, by, bc, paradas, w, hud, children}) => (
  <AbsoluteFill style={{background: '#10101A'}}>
    <Textura tipo={tipo} base={base} linea={linea} luz={luz} semilla={semilla} />
    <Camara paradas={paradas}>
      <Brillo x={bx} y={by} r={720} color={bc} />
      <Mundo w={w}>{children}</Mundo>
    </Camara>
    {hud}
  </AbsoluteFill>
);

// ---------- personas ----------
type PP = {x: number; y: number; sc?: number; camisa?: string; pantalon?: string; pelo?: string; piel?: string; vestido?: boolean; sombrero?: string; coleta?: boolean; larga?: boolean; gafas?: boolean; fase?: number; aD?: number; aI?: number; cara?: 'n' | 's' | 'r' | 'a'; op?: number; silbato?: boolean; sinD?: boolean; sinI?: boolean; chaleco?: string};
const Persona: React.FC<PP> = ({x, y, sc = 1.4, camisa = '#E8856A', pantalon = '#3A4A6A', pelo = '#5A3A22', piel = '#F1C9A5', vestido = false, sombrero, coleta = false, larga = false, gafas = false, fase = 0, aD = 12, aI = -12, cara = 'n', op = 1, silbato = false, sinD = false, sinI = false, chaleco}) => {
  const bob = Math.abs(Math.sin(fase)) * 5;
  const sw = Math.sin(fase) * 28;
  const brazo = (px: number, ang: number, k: string) => {
    const a = (ang * Math.PI) / 180, ex = px + Math.sin(a) * 88, ey = -182 + Math.cos(a) * 88;
    return <g key={k}><line x1={px} y1={-182} x2={ex} y2={ey} stroke={camisa} strokeWidth={20} strokeLinecap="round" /><circle cx={ex} cy={ey} r={11} fill={piel} /></g>;
  };
  return (
    <g transform={`translate(${x} ${y - bob}) scale(${sc})`} opacity={op}>
      <ellipse cx={0} cy={4 + bob} rx={64} ry={9} fill="rgba(0,0,0,0.2)" />
      {[-1, 1].map((k) => <g key={k}><line x1={k * 13} y1={-110} x2={k * 13 + Math.sin(fase + (k > 0 ? 0 : Math.PI)) * 30} y2={-10} stroke={vestido ? piel : pantalon} strokeWidth={21} strokeLinecap="round" /><ellipse cx={k * 13 + Math.sin(fase + (k > 0 ? 0 : Math.PI)) * 30 + 4} cy={-6} rx={17} ry={9} fill="#3A2A22" /></g>)}
      {larga && <rect x={-43} y={-266} width={86} height={104} rx={36} fill={pelo} />}
      {vestido ? <path d="M -28 -192 L 28 -192 L 60 -72 L -60 -72 Z" fill={camisa} stroke={camisa} strokeWidth={10} strokeLinejoin="round" /> : <rect x={-30} y={-196} width={60} height={98} rx={26} fill={camisa} />}
      {chaleco && <g><rect x={-30} y={-196} width={60} height={98} rx={26} fill={chaleco} opacity={0.95} /><rect x={-6} y={-196} width={12} height={98} fill="#fff" opacity={0.5} /></g>}
      {!sinI && brazo(-26, aI + sw, 'i')}
      {!sinD && brazo(26, aD - sw, 'd')}
      {coleta && <ellipse cx={-50} cy={-214} rx={12} ry={32} fill={pelo} transform={`rotate(${18 + Math.sin(fase + 1) * 10} -40 -246)`} />}
      <circle cx={0} cy={-232} r={39} fill={piel} stroke="rgba(90,50,30,0.35)" strokeWidth={3} />
      <path d="M -40 -234 C -45 -292 45 -292 40 -234 C 28 -262 -28 -262 -40 -234 Z" fill={pelo} />
      <ellipse cx={-24} cy={-218} rx={8} ry={5} fill="rgba(235,110,110,0.3)" /><ellipse cx={24} cy={-218} rx={8} ry={5} fill="rgba(235,110,110,0.3)" />
      {[-14, 14].map((ex) => <g key={ex}><ellipse cx={ex} cy={-232} rx={5} ry={cara === 'a' ? 9 : 7} fill="#241410" /><circle cx={ex + 1.8} cy={-235} r={2.2} fill="#fff" /></g>)}
      {cara === 's' && <><path d="M -24 -248 L -7 -243" stroke={pelo} strokeWidth={4.5} strokeLinecap="round" /><path d="M 24 -248 L 7 -243" stroke={pelo} strokeWidth={4.5} strokeLinecap="round" /></>}
      {cara === 'a' && <><path d="M -24 -246 L -7 -254" stroke={pelo} strokeWidth={4.5} strokeLinecap="round" /><path d="M 24 -246 L 7 -254" stroke={pelo} strokeWidth={4.5} strokeLinecap="round" /></>}
      {cara === 'r' && <><path d="M -24 -250 Q -14 -256 -6 -250" stroke={pelo} strokeWidth={4.5} fill="none" strokeLinecap="round" /><path d="M 24 -250 Q 14 -256 6 -250" stroke={pelo} strokeWidth={4.5} fill="none" strokeLinecap="round" /></>}
      {cara === 'n' && <path d="M -12 -214 Q 0 -203 12 -214" stroke="#7A3A2A" strokeWidth={4.5} fill="none" strokeLinecap="round" />}
      {cara === 'r' && <path d="M -16 -216 Q 0 -196 16 -216 Z" fill="#8A3A2A" stroke="#7A3A2A" strokeWidth={3} strokeLinejoin="round" />}
      {cara === 's' && <path d="M -10 -211 L 10 -211" stroke="#7A3A2A" strokeWidth={4.5} strokeLinecap="round" />}
      {cara === 'a' && <ellipse cx={0} cy={-209} rx={7} ry={9} fill="#5A2A20" />}
      {gafas && <g stroke="#2A2A30" strokeWidth={3.5} fill="rgba(255,255,255,0.15)"><circle cx={-14} cy={-232} r={13} /><circle cx={14} cy={-232} r={13} /><line x1={-1} y1={-232} x2={1} y2={-232} /></g>}
      {silbato && <g><rect x={-9} y={-210} width={18} height={9} rx={4} fill="#F5D02A" stroke="#A8841A" strokeWidth={2} /><path d="M -9 -205 Q -30 -190 -26 -160" stroke="#F5D02A" strokeWidth={3} fill="none" /></g>}
      {sombrero && <g><path d="M -38 -258 C -38 -306 38 -306 38 -258 Z" fill={sombrero} /><ellipse cx={0} cy={-258} rx={66} ry={12} fill={sombrero} stroke="rgba(120,90,40,0.5)" strokeWidth={3} /><path d="M -38 -262 Q 0 -250 38 -262" stroke="#F08FA8" strokeWidth={9} fill="none" /></g>}
    </g>
  );
};

// brazo con dos tramos (codo) hacia un punto, para borrar el pizarrón
const BrazoIK: React.FC<{sx: number; sy: number; tx: number; ty: number; l1?: number; l2?: number; color: string; piel: string}> = ({sx, sy, tx, ty, l1 = 100, l2 = 100, color, piel}) => {
  let dx = tx - sx, dy = ty - sy;
  let d = Math.hypot(dx, dy);
  const maxd = l1 + l2 - 2;
  if (d > maxd) { dx *= maxd / d; dy *= maxd / d; d = maxd; }
  const base = Math.atan2(dy, dx), a = Math.acos(Math.max(-1, Math.min(1, (l1 * l1 + d * d - l2 * l2) / (2 * l1 * d))));
  const ex = sx + Math.cos(base + a) * l1, ey = sy + Math.sin(base + a) * l1;
  const hx = sx + dx, hy = sy + dy;
  return <g><line x1={sx} y1={sy} x2={ex} y2={ey} stroke={color} strokeWidth={30} strokeLinecap="round" /><line x1={ex} y1={ey} x2={hx} y2={hy} stroke={color} strokeWidth={26} strokeLinecap="round" /><circle cx={hx} cy={hy} r={16} fill={piel} /></g>;
};

// silueta pequeña de una persona a salvo
const Sil: React.FC<{x: number; y: number; sc?: number; col?: string; op?: number}> = ({x, y, sc = 1, col = '#2E4A5A', op = 1}) => (
  <g transform={`translate(${x} ${y}) scale(${sc})`} opacity={op}><circle cx={0} cy={-34} r={9} fill={col} /><path d="M -11 -22 Q 0 -28 11 -22 L 13 0 L -13 0 Z" fill={col} /></g>
);

// ola dibujada (cuaderno, pizarrón, pantalla)
const OlaDib: React.FC<{x: number; y: number; w: number; h: number; col?: string; line?: string; lw?: number}> = ({x, y, w, h, col = '#3BB3C3', line = '#E9FBFF', lw = 6}) => {
  const {s} = useS();
  const N = 28;
  const pts = Array.from({length: N + 1}).map((_, i) => { const px = (i / N) * w; const py = h * 0.45 - Math.sin((i / N) * Math.PI * 2 - s * 3) * h * 0.26 - (i / N) * h * 0.12; return [px, py]; });
  const top = pts.map((p, i) => `${i ? 'L' : 'M'} ${p[0]} ${p[1]}`).join(' ');
  return (
    <g transform={`translate(${x} ${y})`}>
      <path d={`${top} L ${w} ${h} L 0 ${h} Z`} fill={col} />
      <path d={top} stroke={line} strokeWidth={lw} fill="none" strokeLinecap="round" strokeLinejoin="round" />
      {[0, 1, 2, 3].map((i) => { const k = (i / 4 + s * 0.35) % 1; const px = k * w; const py = h * 0.45 - Math.sin(k * Math.PI * 2 - s * 3) * h * 0.26 - k * h * 0.12; return <circle key={i} cx={px} cy={py - lw * 1.5} r={lw * 0.9} fill={line} opacity={0.85} />; })}
    </g>
  );
};

const Palma: React.FC<{x: number; y: number; sc?: number}> = ({x, y, sc = 1}) => {
  const {s} = useS();
  const sw = Math.sin(s * 1.4 + x * 0.01) * 8;
  return (
    <g transform={`translate(${x} ${y}) scale(${sc})`}>
      <path d={`M 0 0 Q 36 -150 ${14 + sw * 0.3} -300`} stroke="#8A5A32" strokeWidth={24} fill="none" strokeLinecap="round" />
      {[-70, -35, 0, 35, 70, 110].map((a, i) => { const ang = ((a - 90 + sw) * Math.PI) / 180; return <path key={i} d={`M ${14 + sw * 0.3} -300 Q ${14 + Math.cos(ang) * 90} ${-300 + Math.sin(ang) * 60 - 40} ${14 + Math.cos(ang) * 190} ${-300 + Math.sin(ang) * 110 + 30}`} stroke="#3E8A4A" strokeWidth={18} fill="none" strokeLinecap="round" />; })}
    </g>
  );
};

// la costa: cielo, mar, arena mojada y seca
const Costa: React.FC<{x0?: number; w?: number; ret?: number; bub?: number; vapor?: number}> = ({x0 = -600, w = 4200, ret = 0, bub = 0, vapor = 0}) => {
  const {s} = useS();
  const hy = 780, sh = 1100 - 250 * ret, seco = 1160;
  const linea = (y: number, amp: number, k: number) => { let d = `M ${x0} ${y}`; for (let x = x0; x <= x0 + w; x += 60) d += ` L ${x} ${y + Math.sin(x * 0.02 + s * 1.6 + k) * amp}`; return d; };
  const nb = Math.floor(bub * 36);
  return (
    <g>
      <defs>
        <linearGradient id="cieloP" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8ED3E8" /><stop offset="100%" stopColor="#EAF8F2" /></linearGradient>
        <linearGradient id="marP" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#2B9DB5" /><stop offset="100%" stopColor="#4CC7D2" /></linearGradient>
        <linearGradient id="mojadaP" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#B8935A" /><stop offset="100%" stopColor="#D9BB82" /></linearGradient>
      </defs>
      <rect x={x0} y={0} width={w} height={hy} fill="url(#cieloP)" />
      <circle cx={x0 + w * 0.78} cy={520} r={84} fill="#FFF3B8" opacity={0.95} />
      {[0, 1, 2].map((i) => <ellipse key={i} cx={x0 + ((w * (0.2 + 0.3 * i) + s * 14) % w)} cy={430 + i * 70} rx={120} ry={26} fill="#fff" opacity={0.7} />)}
      <rect x={x0} y={hy} width={w} height={sh - hy + 6} fill="url(#marP)" />
      {[0, 1, 2, 3, 4].map((i) => <path key={i} d={linea(hy + ((sh - hy) * (i + 0.7)) / 5.5, 5 + i, i)} stroke="rgba(255,255,255,0.35)" strokeWidth={6} fill="none" />)}
      <rect x={x0} y={sh} width={w} height={seco - sh + 6} fill="url(#mojadaP)" />
      <rect x={x0} y={seco} width={w} height={1920 - seco} fill="#F2D7A0" />
      <path d={linea(sh, 6, 0)} stroke="#FFFFFF" strokeWidth={16} fill="none" opacity={0.9} />
      <path d={linea(sh + 22, 8, 2)} stroke="#FFFFFF" strokeWidth={6} fill="none" opacity={0.5} />
      {Array.from({length: nb}).map((_, i) => { const k = (s * 0.9 + h(i + 7)) % 1; return <circle key={i} cx={x0 + h(i) * w} cy={hy + 40 + h(i + 3) * Math.max(10, sh - hy - 60)} r={(6 + h(i + 5) * 12) * (0.6 + k * 0.6)} fill="rgba(255,255,255,0.45)" stroke="#fff" strokeWidth={2.5} opacity={1 - k * 0.7} />; })}
      {vapor > 0.01 && Array.from({length: 7}).map((_, i) => { const px = x0 + w * (0.08 + i * 0.13), k = (s * 0.5 + h(i + 1)) % 1; return <path key={i} d={`M ${px} ${sh - 20} Q ${px + 30} ${sh - 90} ${px} ${sh - 160} T ${px} ${sh - 300}`} stroke="#fff" strokeWidth={18} fill="none" strokeLinecap="round" opacity={vapor * 0.4 * (1 - k)} transform={`translate(${Math.sin(s * 2 + i) * 14} ${-k * 40})`} />; })}
    </g>
  );
};

// ---------- AULA (E1 y E12-E13) ----------
const NB = {x: 330, y: 1060, w: 420, h: 620};
const Aula: React.FC<{v: 1 | 2}> = ({v}) => {
  const {s, lin, spr} = useS();
  const open = v === 1 ? lin(GEO, GEO + 0.7, 0, 1) : lin(CLASE3 - 0.1, CLASE3 + 0.5, 0.0, 1);
  const sx = interpolate(open, [0, 1], [1, -1], {easing: Easing.inOut(Easing.cubic)});
  const xe = v === 2 ? lin(PROF2 - 0.2, USAR + 0.1, 810, 330) : 810;
  const erasing = v === 2 && s > PROF2 - 0.3;
  const hy2 = 560 + (Math.sin(s * 5) * 0.5 + 0.5) * 110;
  const tx = xe + 154;
  const lineas = Array.from({length: 11}).map((_, i) => NB.y + 130 + i * 46);
  const rows = [{t: 'Ríos y montañas', y: 540}, {t: 'Capitales del mundo', y: 610}, {t: 'Mares y océanos', y: 680}];
  const dots = Array.from({length: 100}).map((_, i) => ({x: 360 + (i % 10) * 40, y: 810 + Math.floor(i / 10) * 21, k: i}));
  const paradas = v === 1
    ? [{t: 0, x: 540, y: 1300, zoom: 1.32}, {t: GEO + 0.15, x: 540, y: 1300, zoom: 1.4}, {t: GEO + 0.9, x: 440, y: 1290, zoom: 1.6}, {t: D2004 - 0.1, x: 440, y: 1280, zoom: 1.72}]
    : [{t: CLASE3 - 0.3, x: 440, y: 1330, zoom: 1.5}, {t: ENVIA, x: 440, y: 1310, zoom: 1.32}, {t: PROF2 - 0.25, x: 540, y: 700, zoom: 1.12}, {t: USAR + 0.6, x: 520, y: 650, zoom: 1.28}];
  const glow = v === 2 ? lin(USAR, USAR + 0.6, 0, 1) : 0;
  return (
    <Lugar tipo="papel" base={v === 1 ? 'linear-gradient(180deg, #A5B8CC 0%, #8FA3B8 55%, #6F8399 100%)' : 'linear-gradient(180deg, #B9C6D0 0%, #A5B0B8 55%, #8A8F90 100%)'} linea="rgba(60,80,110,0.2)" luz={v === 1 ? 'rgba(220,235,250,0.25)' : 'rgba(255,230,180,0.3)'} semilla={v === 1 ? 61 : 62} bx={v === 1 ? 540 : 700} by={v === 1 ? 900 : 700} bc={v === 1 ? 'rgba(200,225,250,0.5)' : 'rgba(255,215,140,0.55)'} paradas={paradas}>
      <rect x={-200} y={200} width={1500} height={720} fill={v === 1 ? '#8FA3B8' : '#A8A8A4'} />
      <rect x={-200} y={860} width={1500} height={50} fill="rgba(0,0,0,0.12)" />
      {/* pizarrón */}
      <rect x={96} y={440} width={888} height={350} rx={14} fill="#7A5A3A" />
      <rect x={116} y={460} width={848} height={310} rx={8} fill="#2F4A44" />
      <rect x={116} y={770} width={848} height={14} fill="#6A4A2A" />
      <defs><clipPath id={`rowsC${v}`}><rect x={-200} y={470} width={xe + 200} height={300} /></clipPath></defs>
      <g clipPath={`url(#rowsC${v})`}>
        {rows.map((r, i) => <text key={i} x={340} y={r.y} fontFamily="Poppins, Arial, sans-serif" fontWeight={700} fontSize={46} fill="#F1EFE3" opacity={0.92}>{r.t}</text>)}
      </g>
      <OlaDib x={140} y={520} w={170} h={110} col="rgba(255,255,255,0.12)" line={glow > 0.01 ? LIMA : '#FFFFFF'} lw={5 + 3 * glow} />
      {glow > 0.01 && <rect x={130} y={500} width={190} height={140} rx={20} fill="none" stroke={LIMA} strokeWidth={5} opacity={glow * (0.6 + 0.3 * Math.sin(s * 6))} />}
      {/* maestro (solo en la segunda aula) */}
      {v === 2 && (
        <g>
          <Persona x={tx} y={1010} sc={1.7} camisa="#7E8590" pantalon="#3A3F4A" pelo="#CFCFCF" gafas sinI cara={s > PROF2 + 0.4 ? 'n' : 's'} aD={14} fase={erasing && s < USAR ? Math.sin(s * 3) * 0.6 : 0} />
          <BrazoIK sx={tx - 44} sy={700} tx={xe} ty={erasing ? hy2 : 600} color="#7E8590" piel="#F1C9A5" />
          <g transform={`translate(${xe - 6} ${erasing ? hy2 : 600})`}><rect x={-50} y={-28} width={100} height={52} rx={8} fill="#B8A07A" stroke="#6A5A3A" strokeWidth={4} /><rect x={-50} y={-28} width={100} height={20} rx={8} fill="#4A3A2A" /></g>
          {erasing && s < USAR + 0.1 && Array.from({length: 8}).map((_, i) => <circle key={i} cx={xe + 30 + h(i) * 50} cy={hy2 + 24 + ((s * 90 + i * 30) % 80)} r={3 + h(i + 4) * 3} fill="rgba(255,255,255,0.7)" opacity={0.7} />)}
        </g>
      )}
      {/* pupitre */}
      <rect x={-200} y={900} width={1500} height={1100} fill="#B07F4F" />
      {Array.from({length: 20}).map((_, i) => <line key={i} x1={-200} y1={940 + i * 54} x2={1300} y2={950 + i * 54} stroke="rgba(90,55,25,0.18)" strokeWidth={5} />)}
      <rect x={-200} y={900} width={1500} height={16} fill="#D6A870" />
      {/* polvo en la luz */}
      {Array.from({length: 14}).map((_, i) => <circle key={i} cx={80 + h(i) * 940} cy={850 + ((h(i + 5) * 900 + s * (10 + h(i) * 14)) % 900)} r={2.5 + h(i + 2) * 3} fill="rgba(255,255,255,0.45)" />)}
      {/* cien personas (E1) */}
      {v === 1 && dots.map((d) => { const p = spr(CIEN1 - 0.05 + d.k * 0.011, 9, 200); return p > 0.01 ? <g key={d.k} transform={`translate(${d.x} ${d.y}) scale(${p * 0.62})`}><circle cx={0} cy={-10} r={7} fill={LIMA} /><path d="M -9 -1 Q 0 -5 9 -1 L 10 12 L -10 12 Z" fill={LIMA} /></g> : null; })}
      {/* cuaderno */}
      <g transform={`rotate(-3 540 1370)`}>
        <rect x={NB.x + 10} y={NB.y + 16} width={NB.w} height={NB.h} rx={12} fill="rgba(0,0,0,0.25)" />
        <rect x={NB.x} y={NB.y} width={NB.w} height={NB.h} rx={10} fill="#FBF6E6" stroke="#D8CFB0" strokeWidth={4} />
        {lineas.map((y, i) => <line key={i} x1={NB.x + 12} y1={y} x2={NB.x + NB.w - 14} y2={y} stroke="rgba(90,130,200,0.4)" strokeWidth={3} />)}
        <line x1={NB.x + 54} y1={NB.y + 14} x2={NB.x + 54} y2={NB.y + NB.h - 14} stroke="rgba(220,90,90,0.5)" strokeWidth={3} />
        {open > 0.4 && <g opacity={clamp01((open - 0.4) * 2.5)}>
