// ---------- MAPA (E10-E11) ----------
const Mapa: React.FC = () => {
  const {s, lin, spr} = useS();
  const rad = lin(GOLP, GOLP + 4.2, 30, 1250, Easing.out(Easing.quad));
  const EP: [number, number] = [860, 1130];
  const masas: {id: string; pts: string; cx: number; cy: number}[] = [
    {id: 'africa', pts: '-60,700 250,760 300,1000 240,1300 130,1500 -60,1450', cx: 120, cy: 1100},
    {id: 'arabia', pts: '260,620 520,560 560,720 440,820 330,760', cx: 420, cy: 700},
    {id: 'india', pts: '560,640 880,600 790,840 700,1060 640,820', cx: 700, cy: 800},
    {id: 'sudeste', pts: '880,600 1160,560 1160,1000 1010,1100 990,980 985,860 960,760 930,690', cx: 1030, cy: 820},
    {id: 'sumatra', pts: '880,1040 1160,1230 1130,1290 870,1110', cx: 1000, cy: 1160},
    {id: 'australia', pts: '640,1560 1000,1480 1160,1700 900,1800 680,1750', cx: 880, cy: 1640},
  ];
  const pulso = (cx: number, cy: number) => clamp01(1 - Math.abs(rad - Math.hypot(cx - EP[0], cy - EP[1])) / 110);
  const luz = spr(NADIE - 0.05, 8, 130);
  const mai = lin(PERO, NADIE, 0, 1);
  return (
    <Lugar tipo="fibra" base="radial-gradient(circle at 50% 45%, #4B6068 0%, #34464F 60%, #233036 100%)" linea="rgba(190,210,215,0.16)" luz="rgba(210,230,235,0.1)" semilla={67} bx={600} by={1000} bc="rgba(180,200,205,0.25)"
      hud={<>
        <Chip texto="Océano Índico" x={540} y={440} t0={OCEANO} t1={PERO - 0.2} size={62} color="#C9D4D6" />
        <Chip texto="Mai Khao" x={540} y={440} t0={MAI2} size={62} />
      </>}
      paradas={[{t: ESE - 0.3, x: 560, y: 1000, zoom: 1.0}, {t: COSTAS, x: 600, y: 1000, zoom: 1.06}, {t: PERO, x: 600, y: 1000, zoom: 1.1}, {t: ISLA - 0.3, x: 890, y: 920, zoom: 2.2}, {t: NADIE + 0.5, x: 930, y: 880, zoom: 3.4}]}>
      {Array.from({length: 14}).map((_, i) => <line key={'a' + i} x1={-100} y1={500 + i * 130} x2={1300} y2={500 + i * 130} stroke="rgba(200,220,225,0.07)" strokeWidth={3} />)}
      {Array.from({length: 9}).map((_, i) => <line key={'b' + i} x1={i * 160} y1={400} x2={i * 160} y2={1900} stroke="rgba(200,220,225,0.07)" strokeWidth={3} />)}
      {masas.map((m) => { const p = pulso(m.cx, m.cy); return <polygon key={m.id} points={m.pts} fill={`rgba(${110 + 70 * p},${124 + 62 * p},${128 + 60 * p},1)`} stroke={p > 0.2 ? '#E6EEF0' : '#9AA8AC'} strokeWidth={8 + 4 * p} strokeLinejoin="round" />; })}
      <ellipse cx={928} cy={906} rx={30} ry={64} transform="rotate(8 928 906)" fill="#6E7C80" stroke="#9AA8AC" strokeWidth={5} />
      {s > GOLP - 0.3 && [0, 1, 2].map((k) => { const r = rad - k * 110; return r > 20 ? <circle key={k} cx={EP[0]} cy={EP[1]} r={r} fill="none" stroke="#DDE6E8" strokeWidth={9 - k * 2} opacity={Math.max(0, (1 - r / 1300) * (1 - k * 0.25))} /> : null; })}
      {s > GOLP - 0.3 && <circle cx={EP[0]} cy={EP[1]} r={12 + 4 * Math.sin(s * 8)} fill="#DDE6E8" />}
      {/* Mai Khao: se ilumina sola */}
      <circle cx={918} cy={858} r={9 + 3 * mai} fill={luz > 0.05 ? LIMA : '#B8C4C6'} stroke="#fff" strokeWidth={2} />
      {luz > 0.05 && <circle cx={918} cy={858} r={16 + 26 * luz} fill="none" stroke={LIMA} strokeWidth={3} opacity={0.5 + 0.3 * Math.sin(s * 7)} />}
      <Ondas x={918} y={858} t0={NADIE} color={LIMA} radio={300} />
    </Lugar>
  );
};

